'use client'

// ─────────────────────────────────────────────────────────────
// Hook — useBarcodeScanner
// Listens for rapid keystroke sequences generated by physical
// USB / Bluetooth handheld barcode scanners (HID input).
// Scanners type characters at superhuman speed (< 50ms interval)
// followed by Enter.
// ─────────────────────────────────────────────────────────────
import { useEffect, useRef } from 'react'

export interface UseBarcodeScannerOptions {
  onScan: (barcode: string) => void
  enabled?: boolean
  minBarcodeLength?: number
  maxIntervalMs?: number
  /**
   * If true, captures scans even when focused in input/textarea,
   * provided the keystroke interval matches hardware scanner burst speed.
   */
  allowInInputs?: boolean
}

export function useBarcodeScanner({
  onScan,
  enabled = true,
  minBarcodeLength = 3,
  maxIntervalMs = 60,
  allowInInputs = false,
}: UseBarcodeScannerOptions) {
  const bufferRef = useRef<string>('')
  const lastKeyTimeRef = useRef<number>(0)
  const isBurstRef = useRef<boolean>(false)

  useEffect(() => {
    if (!enabled) return

    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore functional modifier keys
      if (e.ctrlKey || e.altKey || e.metaKey) return

      const now = Date.now()
      const timeSinceLastKey = now - lastKeyTimeRef.current
      lastKeyTimeRef.current = now

      const target = e.target as HTMLElement | null
      const isInput =
        target &&
        (target.tagName === 'INPUT' ||
          target.tagName === 'TEXTAREA' ||
          target.isContentEditable)

      // If user is typing manually in an input and allowInInputs is false, ignore
      if (isInput && !allowInInputs) {
        bufferRef.current = ''
        isBurstRef.current = false
        return
      }

      if (e.key === 'Enter') {
        const barcode = bufferRef.current.trim()
        bufferRef.current = ''

        if (barcode.length >= minBarcodeLength && isBurstRef.current) {
          e.preventDefault()
          e.stopPropagation()
          isBurstRef.current = false
          onScan(barcode)
        } else {
          isBurstRef.current = false
        }
        return
      }

      // Single printable character
      if (e.key.length === 1) {
        if (timeSinceLastKey <= maxIntervalMs) {
          isBurstRef.current = true
          bufferRef.current += e.key
        } else {
          // Reset buffer if delay too long (manual human typing)
          bufferRef.current = e.key
          isBurstRef.current = false
        }
      }
    }

    window.addEventListener('keydown', handleKeyDown, true)
    return () => {
      window.removeEventListener('keydown', handleKeyDown, true)
    }
  }, [enabled, onScan, minBarcodeLength, maxIntervalMs, allowInInputs])
}
